import * as T from './vendor/three.module.min.js';
import {preloadGarden81 as preloadOld,gardenMaterials81 as oldMaterials} from './tiki-garden-materials-v81.js';
const cache=new Map(),ROOT=new URL('./textures/tiki-garden-v85/',import.meta.url);
const plantFile={"banana": "banana-leaf-clump", "philodendron": "split-leaf-philodendron-v2", "croton": "multicolored-croton", "cordyline": "red-cordyline", "pineapple": "pineapple-growing-plant"};
const files=['walls/lava-rock-basecolor.webp','walls/lava-rock-normal.webp','walls/lava-rock-roughness.webp','walls/lava-rock-height.webp','walls/lava-rock-ao.webp',...Array.from({length:4},(_,i)=>`walls/rainforest-0${i+1}.webp`),...['banana','philodendron','croton','cordyline','pineapple'].map(n=>`plants/runtime/${plantFile[n]}-1024.webp`),...['basecolor','normal','roughness'].map(n=>`../tiki-v76/carved-wood/${n}.png`)];
export async function preloadGarden81(report=()=>{}){await preloadOld(p=>report(p*.55));let cursor=0,done=0;const loader=new T.TextureLoader();await Promise.all(Array.from({length:3},async()=>{while(cursor<files.length){const f=files[cursor++];if(!cache.has(f)){const t=await loader.loadAsync(new URL(f,ROOT).href);t.colorSpace=/normal|roughness|height|ao/.test(f)?T.NoColorSpace:T.SRGBColorSpace;t.wrapS=t.wrapT=f.includes('lava')?T.RepeatWrapping:T.ClampToEdgeWrapping;t.anisotropy=4;cache.set(f,t);}report(.55+.45*++done/files.length);}}));}
export function gardenMaterials81(){const base=oldMaterials(),m=base.m;
 m.wall=new T.MeshStandardMaterial({name:'V85 matte recessed lava masonry',map:cache.get(files[0]),normalMap:cache.get(files[1]),normalScale:new T.Vector2(.75,.75),roughnessMap:cache.get(files[2]),roughness:1,metalness:0,aoMap:cache.get(files[4]),aoMapIntensity:.4});
 m.wood=new T.MeshStandardMaterial({name:'Old carved timber / existing generated PBR wood',map:cache.get('../tiki-v76/carved-wood/basecolor.png'),normalMap:cache.get('../tiki-v76/carved-wood/normal.png'),roughnessMap:cache.get('../tiki-v76/carved-wood/roughness.png'),roughness:.88,normalScale:new T.Vector2(.65,.65),color:0xcac0a5});
 m.rim=m.wall.clone();m.rim.color.setHex(0xc6c0ab);m.rock=m.boulder;
 for(let i=1;i<=4;i++)m['rainforest'+i]=new T.MeshStandardMaterial({name:'Independent photographic rainforest scenic panel '+i,map:cache.get(`walls/rainforest-0${i}.webp`),roughness:.98,emissiveMap:cache.get(`walls/rainforest-0${i}.webp`),emissive:0xffffff,emissiveIntensity:.13});
 for(const n of ['banana','philodendron','croton','cordyline','pineapple']){m[n]=new T.MeshStandardMaterial({name:'Generated botanical cutout / '+n,map:cache.get(`plants/runtime/${plantFile[n]}-1024.webp`),alphaTest:.38,side:T.DoubleSide,roughness:.88});m[n].forceSinglePass=true;}
 m.redEye=m.dark.clone();m.redEye.color.setHex(0x393429);m.frosted=new T.MeshStandardMaterial({name:'Frosted safety glazing',color:0xa3b8ab,roughness:.88,metalness:.06,normalMap:base.texture('surfaces','wall','normal'),normalScale:new T.Vector2(.045,.045),emissive:0xa5b7a4,emissiveIntensity:.13});
 m.ceiling.emissiveMap=m.ceiling.map;m.ceiling.emissive.setHex(0xffffff);m.ceiling.emissiveIntensity=.13;
 return{...base,m,textures:[...base.textures,...cache.values()]};}
